extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var validator = await instantiate_script("res://story/story_validator.gd")
	if not check("validator_esiste", validator != null, "Lo script res://story/story_validator.gd deve esistere e caricarsi"):
		return
	if not check("ha_find_unreachable", has_function(validator, "find_unreachable_labels"), "StoryValidator deve avere la funzione find_unreachable_labels"):
		return
	var unreach_branch: Array = validator.find_unreachable_labels("res://story/branching_story.json")
	check("branch_nessun_orfano", unreach_branch.is_empty(), "In branching_story.json tutte le etichette sono collegate")
	var file_orphan := "user://test_orphan_label.json"
	var f1 := FileAccess.open(file_orphan, FileAccess.WRITE)
	f1.store_string(JSON.stringify({
		"lines": [
			{"type": "line", "speaker": "Elena", "text": "Inizio."},
			{"type": "jump", "target": "fine"},
			{"type": "label", "id": "orfano"},
			{"type": "label", "id": "fine"}
		]
	}))
	f1.close()
	var unreach_orphan: Array = validator.find_unreachable_labels(file_orphan)
	check("trova_orfano", unreach_orphan.has("orfano") and not unreach_orphan.has("fine"), "Deve identificare 'orfano' come irraggiungibile senza segnalare 'fine'")

